#!/usr/bin/env bash
# Regression: the omp launcher generated by install.sh must honor the
# install-time LIB_DIR (OMP_LIB_DIR), forward arguments, and set
# OMP_PLATFORM=android. Executes the real heredoc block; no install/download.
# Usage: test-install-launcher.sh [path/to/install.sh]
# Temp root: $TMPDIR, else $PREFIX/tmp (pass TMPDIR explicitly on CI if needed).
set -euo pipefail
src=${1:-$(CDPATH= cd -- "$(dirname -- "$0")/../.." && pwd -P)/install.sh}
tmp_base=${TMPDIR:-${PREFIX:?set PREFIX or TMPDIR}/tmp}
root=$(mktemp -d "$tmp_base/omp-launcher-test.XXXXXX")
trap 'rm -rf "$root"' EXIT
fail() { echo "FAIL: $*" >&2; exit 1; }
quote() { printf "'%s'" "${1//\'/\'\\\'\'}"; }

awk '/^cat > "\$BIN_DIR\/omp" <<EOF$/{on=1} on{print} /^EOF$/{on=0}' "$src" > "$root/block.sh"
grep -qx 'EOF' "$root/block.sh" || fail "launcher heredoc not found in $src"
mkdir -p "$root/bin" "$root/prefix"

fake_app() { # dir
	mkdir -p "$1"
	cat > "$1/bun" <<'SH'
#!/bin/sh
printf 'SELF=%s\nCLI=%s\nPLATFORM=%s\nPRELOAD=%s\n' "$0" "${1-}" "${OMP_PLATFORM-}" "${LD_PRELOAD-}"
shift || true
for a in "$@"; do printf 'ARG=%s\n' "$a"; done
SH
	chmod 755 "$1/bun"
	: > "$1/cli.js"
}

run_launcher() { # lib_dir
	{
		echo '#!/bin/sh'
		printf 'BIN_DIR=%s\nPREFIX_DIR=%s\nLIB_DIR=%s\n' \
			"$(quote "$root/bin")" "$(quote "$root/prefix")" "$(quote "$1")"
		cat "$root/block.sh"
		printf 'chmod 755 %s\n' "$(quote "$root/bin/omp")"
	} > "$root/gen.sh"
	env -u PREFIX -u OMP_LIB_DIR -u LD_PRELOAD sh "$root/gen.sh"
	env -u PREFIX -u OMP_LIB_DIR -u LD_PRELOAD "$root/bin/omp" --version 'two words'
}

# Path with spaces: quoting/injection regression for the generated assignments.
app="$root/custom lib"
fake_app "$app"
out=$(run_launcher "$app") || fail 'generated launcher exited nonzero (see stderr)'
expected=$(printf 'SELF=%s\nCLI=%s\nPLATFORM=android\nPRELOAD=\nARG=--version\nARG=two words' "$app/bun" "$app/cli.js")
[ "$out" = "$expected" ] || fail "unexpected launcher output:
$out"
echo 'PASS launcher path, platform, args'

# Optional preload check: only when the platform has a usable preload library.
# LD_PRELOAD cannot name a path containing spaces, so use a separate app dir.
preload=""
candidates=("${OMP_TEST_PRELOAD_LIB:-}" /system/lib64/libdl.so)
if command -v ldconfig >/dev/null 2>&1; then
	p=$(ldconfig -p 2>/dev/null | awk '/libdl\.so/{print $NF; exit}') || true
	candidates+=("$p")
fi
for c in "${candidates[@]}"; do
	if [ -n "$c" ] && [ -r "$c" ] && LD_PRELOAD=$c sh -c ':' 2>/dev/null; then
		preload=$c
		break
	fi
done
if [ -n "$preload" ]; then
	app="$root/app-preload"
	fake_app "$app"
	cp -L "$preload" "$app/libomp-compat.so"
	out=$(run_launcher "$app") || fail 'generated launcher exited nonzero (see stderr)'
	expected=$(printf 'SELF=%s\nCLI=%s\nPLATFORM=android\nPRELOAD=%s\nARG=--version\nARG=two words' "$app/bun" "$app/cli.js" "$app/libomp-compat.so")
	[ "$out" = "$expected" ] || fail "unexpected preload output:
$out"
	echo 'PASS launcher preload'
else
	echo 'SKIP launcher preload (no usable preload library)'
fi
